// Demo: Dictionary Training — codec race on a sample
function fakeRatio(codec,size,seed){var base={'zstd':0.32,'brotli':0.28,'gzip':0.38,'lz4':0.55}[codec];return base+((seed%7)/100);}
function fakeSpeed(codec){return {'zstd':450,'brotli':12,'gzip':120,'lz4':2600}[codec];}
var size=2*1000;
console.log('technique: Dictionary Training');console.log('sample: '+(size/1000)+' KB');
['zstd','brotli','gzip','lz4'].forEach(function(c){console.log(c+': ratio '+fakeRatio(c,size,1).toFixed(2)+', '+fakeSpeed(c)+' MB/s');});
console.log('winner depends on the ratio/speed tradeoff for this data');

// Demo: Content-Type Detection — entropy decides whether compression pays
function entropy(s){var f={},h=0;for(var i=0;i<s.length;i++){f[s[i]]=(f[s[i]]||0)+1;}
Object.keys(f).forEach(function(k){var p=f[k]/s.length;h-=p*Math.log2(p);});return h;}
var text='',rand='';for(var i=0;i<8*10;i++){text+='abcdefgh'[i%8];rand+=String.fromCharCode(32+((i*7919+2)%95));}
var et=entropy(text),er=entropy(rand);
console.log('technique: Content-Type Detection');console.log('text entropy: '+et.toFixed(2)+' bits/char -> COMPRESS');
console.log('random entropy: '+er.toFixed(2)+' bits/char -> '+(er>6?'SKIP (already dense)':'COMPRESS'));

