// Demo: Columnar Encoding Selection — run-length vs dictionary encoding choice
function runs(a){var r=1;for(var i=1;i<a.length;i++){if(a[i]!==a[i-1])r++;}return r;}
var col=[];for(var i=0;i<31;i++){col.push((i*7+5)%(26%4+2));}
var r=runs(col),distinct={};col.forEach(function(v){distinct[v]=1;});var nd=Object.keys(distinct).length;
console.log('technique: Columnar Encoding Selection');console.log('column values: '+col.length+', runs: '+r+', distinct: '+nd);
console.log(r<col.length/2?'choice: RLE (long runs)':nd<16?'choice: DICTIONARY (low cardinality)':'choice: PLAIN (incompressible pattern)');

